#!/usr/bin/env bash
# hassette: rerun jscpd default + weak with generated ("Do not edit this file directly") files excluded.
F="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
J="${JSCPD:-jscpd}"
O=${OUT:-$F/results}/hassette
H="${HASSETTE:?set HASSETTE to a hassette checkout}"
G="${GATE_CLUSTERS:?set GATE_CLUSTERS to the PMD gate cluster listing (cpd-plain.txt)}"
# Optional tuning knobs; unset means jscpd's defaults. Each combination gets its own output suffix.
TUNE=()
SUF=""
if [ -n "${MINTOK:-}" ]; then TUNE+=(--min-tokens "$MINTOK"); SUF="$SUF-k$MINTOK"; fi
if [ -n "${MAXGAP:-}" ]; then TUNE+=(--max-gap-lines "$MAXGAP"); SUF="$SUF-gap$MAXGAP"; fi
cd "$H" || exit 1
grep -l "Do not edit this file directly" $(cat "$O/all.txt") >"$O/generated.txt"
echo "generated files: $(wc -l <"$O/generated.txt")"; cat "$O/generated.txt"
grep -vxF -f "$O/generated.txt" "$O/all.txt" >"$O/all-nogen.txt"
python3 -I -c 'import json,sys; print(json.dumps({"path": [sys.argv[2] + "/" + l.strip() for l in open(sys.argv[1]) if l.strip()]}))' "$O/all-nogen.txt" "$H" >"$O/jscpd-paths-nogen.json"
cd /tmp || exit 1
for m in mild weak; do
  R="nogen-$m$SUF"
  rm -rf "${O:?}/$R"
  mkdir -p "$O/$R"
  if ! "$J" -c "$O/jscpd-paths-nogen.json" --no-gitignore --absolute --mode $m "${TUNE[@]}" --reporters json,silent --output "$O/$R" --no-tips >"$O/$R/jscpd.log" 2>&1; then
    echo "jscpd failed for $R; see $O/$R/jscpd.log" >&2
    exit 1
  fi
  echo "== $R"
  python3 -I "$F/scripts/clusters.py" "$O/$R/jscpd-report.json" --root "$H/" | head -5
  python3 -I "$F/scripts/clusters.py" "$O/$R/jscpd-report.json" --root "$H/" --list >"$O/clusters-$R.txt"
  python3 -I "$F/scripts/compare_gate.py" "$G" "$O/$R/jscpd-report.json" "$H/"
done
